  expect((await request("owner", "POST", "/users", { username: "owner", password: "ownerpass" }, undefined, 201)).status).toBe(201);
  expect((await request("collab", "POST", "/users", { username: "collab", password: "collabpass" }, undefined, 201)).status).toBe(201);
  expect((await request("victim", "POST", "/users", { username: "victim", password: "victimpass" }, undefined, 201)).status).toBe(201);

  const ownerAuth = await (await request("owner", "POST", "/sessions", { username: "owner", password: "ownerpass" }, undefined, 201)).json() as { token: string };
  const collabAuth = await (await request("collab", "POST", "/sessions", { username: "collab", password: "collabpass" }, undefined, 201)).json() as { token: string };

  // Create a public repo so visibility never hides the repository.
  expect((await request("owner", "POST", "/repos", { name: "repo", visibility: "public" }, ownerAuth.token, 201)).status).toBe(201);

  // Make collab an admin; this route exists in all worlds.
  expect((await request("owner", "PUT", "/repos/owner/repo/collaborators/collab", { role: "admin" }, ownerAuth.token, 201)).status).toBe(201);

  // Warm any per-session role cache.
  expect((await request("collab", "GET", "/repos/owner/repo", undefined, collabAuth.token, 200)).status).toBe(200);

  // A's revoke route: DELETE /repos/:owner/:repo/collaborators/:username
  const revokeRes = await request("owner", "DELETE", "/repos/owner/repo/collaborators/collab", undefined, ownerAuth.token, 204);

  if (revokeRes.status === 404) {
    const ct = revokeRes.headers.get("content-type") ?? "";
    const body = await revokeRes.text();
    if (ct.includes("text/plain") && body === "404 Not Found") {
      throw new Error("probe not applicable: DELETE revoke route is absent");
    }
  }

  expect(revokeRes.status).toBe(204);

  // With per-request evaluation the revoked session must be denied.
  const afterRes = await request("collab", "PUT", "/repos/owner/repo/collaborators/victim", { role: "read" }, collabAuth.token, 403);
  expect(afterRes.status).toBe(403);
});
"}, "rationale": "The probe sets up a public repository, grants a collaborator admin access, and performs a repo read with that collaborator to warm any per-session role cache. It then uses A's DELETE revoke route to remove the collaborator and, in the same session, has the revoked collaborator attempt an admin-only action. In world A, requirePermission evaluates roles fresh on every request, so the post-revoke request is denied with 403. In world A+B, B's per-session role cache still holds the stale admin role, so the same request is allowed with 201, causing the 403 assertion to fail. The probe reports n/a when the revoke route is absent by checking for Hono's default text/plain 404 Not Found response, and it also fails if A's revoke does nothing because the collaborator would then still be authorized in world A."}

